/*
 * ui_draw.c - tiny immediate-mode RGBA renderer for the switch_rdp UI.
 *
 * Everything the app shows is drawn into one RGBA8888 target (normally the
 * framebuffer's linear buffer).  There is no console any more: mixing
 * consoleInit()/framebufferClose() on the same window was what crashed the
 * console on L+R exit (PC wandered into the heap), and libnx's console font
 * cannot show Chinese anyway.  Text comes from ui_font.c (an 8x16 ASCII /
 * 16x16 CJK bitmap font generated by tools/gen_ui_font.py).
 */

#include <stdint.h>
#include <string.h>

#include "ui_draw.h"
#include "ui_font.h"

static uint8_t*  s_dst;
static uint32_t  s_stride;
static int       s_w, s_h;

void ui_target(void* dst, uint32_t stride, int w, int h)
{
    s_dst = (uint8_t*)dst;
    s_stride = stride;
    s_w = w;
    s_h = h;
}

void ui_clear(uint8_t r, uint8_t g, uint8_t b)
{
    int y;
    if (!s_dst) return;
    for (y = 0; y < s_h; y++)
    {
        uint8_t* row = s_dst + (size_t)y * s_stride;
        int x;
        for (x = 0; x < s_w; x++)
        {
            row[x * 4 + 0] = r;
            row[x * 4 + 1] = g;
            row[x * 4 + 2] = b;
            row[x * 4 + 3] = 0xFF;
        }
    }
}

/* alpha 0..255; blends over what is already there */
void ui_rect(int x, int y, int w, int h, uint8_t r, uint8_t g, uint8_t b, uint8_t a)
{
    int i, j;
    if (!s_dst || a == 0) return;
    if (x < 0) { w += x; x = 0; }
    if (y < 0) { h += y; y = 0; }
    if (x + w > s_w) w = s_w - x;
    if (y + h > s_h) h = s_h - y;
    if (w <= 0 || h <= 0) return;

    for (j = 0; j < h; j++)
    {
        uint8_t* p = s_dst + (size_t)(y + j) * s_stride + (size_t)x * 4;
        if (a == 255)
        {
            for (i = 0; i < w; i++, p += 4)
            { p[0] = r; p[1] = g; p[2] = b; p[3] = 0xFF; }
        }
        else
        {
            for (i = 0; i < w; i++, p += 4)
            {
                p[0] = (uint8_t)((r * a + p[0] * (255 - a)) / 255);
                p[1] = (uint8_t)((g * a + p[1] * (255 - a)) / 255);
                p[2] = (uint8_t)((b * a + p[2] * (255 - a)) / 255);
                p[3] = 0xFF;
            }
        }
    }
}

int ui_text_w(const char* s, int scale)
{
    int w = 0;
    const unsigned char* p = (const unsigned char*)s;
    while (*p)
    {
        uint32_t cp;
        if (*p < 0x80) cp = *p++;
        else if ((*p & 0xE0) == 0xC0) { cp = *p++ & 0x1F; if ((*p & 0xC0) == 0x80) cp = (cp << 6) | (*p++ & 0x3F); }
        else if ((*p & 0xF0) == 0xE0) { cp = *p++ & 0x0F; for (int k = 0; k < 2 && (*p & 0xC0) == 0x80; k++) cp = (cp << 6) | (*p++ & 0x3F); }
        else { cp = *p++ & 0x07; for (int k = 0; k < 3 && (*p & 0xC0) == 0x80; k++) cp = (cp << 6) | (*p++ & 0x3F); }

        const ui_glyph* gl = ui_font_lookup(cp);
        if (!gl) gl = ui_font_lookup('?');
        if (!gl) continue;
        w += (gl->w * scale) + scale;      /* one pixel of letter spacing */
    }
    return w;
}

void ui_text(int x, int y, int scale, uint8_t r, uint8_t g, uint8_t b, const char* s)
{
    const unsigned char* p = (const unsigned char*)s;
    if (!s_dst || scale < 1) return;

    while (*p)
    {
        uint32_t cp;
        if (*p < 0x80) cp = *p++;
        else if ((*p & 0xE0) == 0xC0) { cp = *p++ & 0x1F; if ((*p & 0xC0) == 0x80) cp = (cp << 6) | (*p++ & 0x3F); }
        else if ((*p & 0xF0) == 0xE0) { cp = *p++ & 0x0F; for (int k = 0; k < 2 && (*p & 0xC0) == 0x80; k++) cp = (cp << 6) | (*p++ & 0x3F); }
        else { cp = *p++ & 0x07; for (int k = 0; k < 3 && (*p & 0xC0) == 0x80; k++) cp = (cp << 6) | (*p++ & 0x3F); }

        const ui_glyph* gl = ui_font_lookup(cp);
        if (!gl) gl = ui_font_lookup('?');
        if (!gl) continue;

        {
            int stride = (gl->w + 7) / 8;
            const uint8_t* bits = ui_font_bits + gl->off;
            int gx, gy, sx, sy;
            for (gy = 0; gy < UI_FONT_CELL_H; gy++)
            {
                const uint8_t* row = bits + (size_t)gy * stride;
                for (gx = 0; gx < gl->w; gx++)
                {
                    if (!(row[gx >> 3] & (0x80 >> (gx & 7)))) continue;
                    for (sy = 0; sy < scale; sy++)
                    {
                        int dy = y + gy * scale + sy;
                        int dx0 = x + gx * scale;
                        if (dy < 0 || dy >= s_h) continue;
                        for (sx = 0; sx < scale; sx++)
                        {
                            int dx = dx0 + sx;
                            uint8_t* d;
                            if (dx < 0 || dx >= s_w) continue;
                            d = s_dst + (size_t)dy * s_stride + (size_t)dx * 4;
                            d[0] = r; d[1] = g; d[2] = b; d[3] = 0xFF;
                        }
                    }
                }
            }
            x += (gl->w * scale) + scale;
        }
    }
}

void ui_text_center(int cx, int y, int scale, uint8_t r, uint8_t g, uint8_t b, const char* s)
{
    ui_text(cx - ui_text_w(s, scale) / 2, y, scale, r, g, b, s);
}

void ui_frame(int x, int y, int w, int h, uint8_t r, uint8_t g, uint8_t b, uint8_t a)
{
    ui_rect(x, y, w, 2, r, g, b, a);
    ui_rect(x, y + h - 2, w, 2, r, g, b, a);
    ui_rect(x, y, 2, h, r, g, b, a);
    ui_rect(x + w - 2, y, 2, h, r, g, b, a);
}
